  "inlineSchema": "// Schéma Prisma — SQLite en dev, PostgreSQL en prod (changer provider + DATABASE_URL).\n// SQLite ne supporte pas les enums Prisma : les champs `type`, `sex` et `role`\n// sont des String contraintes par le code applicatif.\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../lib/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ---------------------------------------------------------------------------\n// Auth — tables requises par Better Auth 1.7 (vérifiées contre la définition\n// embarquée dans le paquet : voir getAuthTables).\n// ---------------------------------------------------------------------------\n\nmodel User {\n  id              String   @id\n  name            String\n  email           String   @unique\n  emailVerified   Boolean  @default(false)\n  image           String?\n  // Admin de la plateforme : dashboard global, lecture seule de toutes les\n  // familles, création de familles et nomination des admins famille.\n  isPlatformAdmin Boolean  @default(false)\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @default(now()) @updatedAt\n\n  sessions     Session[]\n  accounts     Account[]\n  person       Person?\n  memberships  TreeMembership[]\n  joinRequests JoinRequest[]\n  proposals    Proposal[]\n\n  @@map(\"user\")\n}\n\nmodel Session {\n  id        String   @id\n  expiresAt DateTime\n  token     String   @unique\n  createdAt DateTime @default(now())\n  updatedAt DateTime @default(now()) @updatedAt\n  ipAddress String?\n  userAgent String?\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@map(\"session\")\n}\n\nmodel Account {\n  id                    String    @id\n  issuer                String\n  accountId             String\n  providerId            String\n  userId                String\n  user                  User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  accessToken           String?\n  refreshToken          String?\n  idToken               String?\n  accessTokenExpiresAt  DateTime?\n  refreshTokenExpiresAt DateTime?\n  scope                 String?\n  password              String?\n  createdAt             DateTime  @default(now())\n  updatedAt             DateTime  @default(now()) @updatedAt\n\n  @@map(\"account\")\n}\n\nmodel Verification {\n  id         String   @id\n  identifier String\n  value      String\n  expiresAt  DateTime\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @default(now()) @updatedAt\n\n  @@map(\"verification\")\n}\n\n// ---------------------------------------------------------------------------\n// Domaine — l'arbre familial.\n// Un User est un compte ; une Person est une carte dans l'arbre. Une Person\n// peut exister sans compte (ancêtres, enfants) et être revendiquée plus tard.\n// ---------------------------------------------------------------------------\n\nmodel Tree {\n  id         String   @id @default(cuid())\n  name       String\n  inviteSlug String?  @unique // lien public de présentation pour les demandes d'adhésion\n  createdAt  DateTime @default(now())\n\n  persons       Person[]\n  relationships Relationship[]\n  memberships   TreeMembership[]\n  invitations   Invitation[]\n  joinRequests  JoinRequest[]\n  proposals     Proposal[]\n}\n\nmodel Person {\n  id        String   @id @default(cuid())\n  treeId    String\n  tree      Tree     @relation(fields: [treeId], references: [id], onDelete: Cascade)\n  name      String\n  nickname  String? // surnom affiché sous le nom, sur la carte et sa fiche\n  sex       String // \"M\" | \"F\"\n  birthYear Int?\n  deathYear Int?\n  deceased  Boolean  @default(false) // marqué·e comme décédé·e (année facultative)\n  photoUrl  String?\n  coverUrl  String? // photo de couverture — au plus une par carte\n  email     String? // contact de la personne — prérempli à l'invitation\n  userId    String?  @unique\n  user      User?    @relation(fields: [userId], references: [id], onDelete: SetNull)\n  createdAt DateTime @default(now())\n\n  relsFrom    Relationship[] @relation(\"from\")\n  relsTo      Relationship[] @relation(\"to\")\n  invitations Invitation[]\n\n  @@index([treeId])\n}\n\n// PARENT : from = parent, to = enfant.\n// SPOUSE : paire non ordonnée (une seule ligne par couple).\nmodel Relationship {\n  id     String @id @default(cuid())\n  treeId String\n  tree   Tree   @relation(fields: [treeId], references: [id], onDelete: Cascade)\n  type   String // \"PARENT\" | \"SPOUSE\"\n  fromId String\n  from   Person @relation(\"from\", fields: [fromId], references: [id], onDelete: Cascade)\n  toId   String\n  to     Person @relation(\"to\", fields: [toId], references: [id], onDelete: Cascade)\n\n  @@unique([type, fromId, toId])\n  @@index([treeId])\n}\n\nmodel TreeMembership {\n  id     String @id @default(cuid())\n  treeId String\n  tree   Tree   @relation(fields: [treeId], references: [id], onDelete: Cascade)\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  role   String @default(\"member\") // \"admin\" | \"parent\" | \"member\"\n\n  @@unique([treeId, userId])\n}\n\n// ---------------------------------------------------------------------------\n// V1.1 — entrées dans la famille et modération de l'arbre.\n// ---------------------------------------------------------------------------\n\n// Invitation ciblée : un lien à usage unique qui relie un nouveau compte\n// à une carte précise de l'arbre.\nmodel Invitation {\n  id        String    @id @default(cuid())\n  treeId    String\n  tree      Tree      @relation(fields: [treeId], references: [id], onDelete: Cascade)\n  personId  String\n  person    Person    @relation(fields: [personId], references: [id], onDelete: Cascade)\n  token     String    @unique\n  role      String    @default(\"member\") // rôle accordé à l'acceptation : \"admin\" | \"parent\" | \"member\"\n  createdBy String // userId de l'émetteur\n  createdAt DateTime  @default(now())\n  expiresAt DateTime\n  usedAt    DateTime?\n  usedBy    String? // userId du compte qui a accepté\n\n  @@index([treeId])\n}\n\n// Demande d'adhésion via le lien de présentation de la famille.\nmodel JoinRequest {\n  id        String    @id @default(cuid())\n  treeId    String\n  tree      Tree      @relation(fields: [treeId], references: [id], onDelete: Cascade)\n  userId    String\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  message   String\n  status    String    @default(\"PENDING\") // \"PENDING\" | \"APPROVED\" | \"REJECTED\"\n  decidedBy String? // userId de l'admin décideur\n  decidedAt DateTime?\n  createdAt DateTime  @default(now())\n\n  @@unique([treeId, userId])\n}\n\n// Proposition de modification de l'arbre par un membre, validée par un admin.\nmodel Proposal {\n  id        String    @id @default(cuid())\n  treeId    String\n  tree      Tree      @relation(fields: [treeId], references: [id], onDelete: Cascade)\n  authorId  String\n  author    User      @relation(fields: [authorId], references: [id], onDelete: Cascade)\n  type      String // \"ADD_MEMBER\" (V1.1)\n  payload   String // JSON — pour ADD_MEMBER : { name, sex, birthYear, relType, anchorId }\n  status    String    @default(\"PENDING\") // \"PENDING\" | \"APPROVED\" | \"REJECTED\"\n  reason    String? // motif de refus, visible par l'auteur\n  decidedBy String?\n  decidedAt DateTime?\n  createdAt DateTime  @default(now())\n\n  @@index([treeId, status])\n}\n",
